    "inlineSchema": "model AiSearchLog {\n  id            String   @id @default(uuid()) @db.Uuid\n  userId        String?  @map(\"user_id\") @db.Uuid\n  user          User?    @relation(fields: [userId], references: [id], onDelete: SetNull)\n  queryText     String   @map(\"query_text\")\n  parsedFilters Json     @map(\"parsed_filters\") @db.JsonB\n  createdAt     DateTime @default(now()) @map(\"created_at\")\n\n  @@map(\"ai_search_logs\")\n}\n\nenum UserRole {\n  TENANT\n  LANDLORD\n  ADMIN\n}\n\nenum ListingStatus {\n  AVAILABLE\n  RENTED\n  INACTIVE\n}\n\nenum InquiryStatus {\n  PENDING\n  RESPONDED\n  CLOSED\n}\n\nmodel Favorite {\n  id        String   @id @default(uuid()) @db.Uuid\n  userId    String   @map(\"user_id\") @db.Uuid\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  listingId String   @map(\"listing_id\") @db.Uuid\n  listing   Listing  @relation(fields: [listingId], references: [id], onDelete: Cascade)\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  @@unique([userId, listingId])\n  @@index([userId])\n  @@map(\"favorites\")\n}\n\nmodel Inquiry {\n  id        String        @id @default(uuid()) @db.Uuid\n  listingId String        @map(\"listing_id\") @db.Uuid\n  listing   Listing       @relation(fields: [listingId], references: [id], onDelete: Cascade)\n  tenantId  String        @map(\"tenant_id\") @db.Uuid\n  tenant    User          @relation(\"TenantInquiries\", fields: [tenantId], references: [id], onDelete: Cascade)\n  message   String\n  status    InquiryStatus @default(PENDING)\n  createdAt DateTime      @default(now()) @map(\"created_at\")\n\n  @@index([listingId])\n  @@map(\"inquiries\")\n}\n\nmodel Listing {\n  id          String        @id @default(uuid()) @db.Uuid\n  landlordId  String        @map(\"landlord_id\") @db.Uuid\n  landlord    User          @relation(\"LandlordListings\", fields: [landlordId], references: [id], onDelete: Cascade)\n  title       String\n  description String\n  price       Decimal       @db.Decimal(10, 2)\n  sizeSqft    Decimal       @map(\"size_sqft\") @db.Decimal(8, 2)\n  bedrooms    Int\n  bathrooms   Int\n  floorNumber Int?          @map(\"floor_number\")\n  address     String\n  area        String\n  city        String\n  latitude    Decimal?      @db.Decimal(10, 7)\n  longitude   Decimal?      @db.Decimal(10, 7)\n  amenities   String[]\n  status      ListingStatus @default(AVAILABLE)\n  createdAt   DateTime      @default(now()) @map(\"created_at\")\n  updatedAt   DateTime      @updatedAt @map(\"updated_at\")\n\n  images    ListingImage[]\n  favorites Favorite[]\n  inquiries Inquiry[]\n  reviews   Review[]\n\n  @@index([city, area])\n  @@index([price])\n  @@index([bedrooms, bathrooms])\n  @@index([status])\n  @@index([latitude, longitude])\n  @@index([amenities], type: Gin)\n  @@map(\"listings\")\n}\n\nmodel ListingImage {\n  id         String  @id @default(uuid()) @db.Uuid\n  listingId  String  @map(\"listing_id\") @db.Uuid\n  listing    Listing @relation(fields: [listingId], references: [id], onDelete: Cascade)\n  imageUrl   String  @map(\"image_url\")\n  isPrimary  Boolean @default(false) @map(\"is_primary\")\n  orderIndex Int     @default(0) @map(\"order_index\")\n\n  @@map(\"listing_images\")\n}\n\nmodel PasswordResetToken {\n  id        String    @id @default(uuid()) @db.Uuid\n  userId    String    @map(\"user_id\") @db.Uuid\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  tokenHash String    @map(\"token_hash\")\n  expiresAt DateTime  @map(\"expires_at\")\n  usedAt    DateTime? @map(\"used_at\")\n\n  @@map(\"password_reset_tokens\")\n}\n\nmodel RefreshToken {\n  id        String   @id @default(uuid()) @db.Uuid\n  userId    String   @map(\"user_id\") @db.Uuid\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  tokenHash String   @map(\"token_hash\")\n  expiresAt DateTime @map(\"expires_at\")\n  revoked   Boolean  @default(false)\n\n  @@map(\"refresh_tokens\")\n}\n\nmodel Review {\n  id        String   @id @default(uuid()) @db.Uuid\n  listingId String   @map(\"listing_id\") @db.Uuid\n  listing   Listing  @relation(fields: [listingId], references: [id], onDelete: Cascade)\n  tenantId  String   @map(\"tenant_id\") @db.Uuid\n  tenant    User     @relation(\"TenantReviews\", fields: [tenantId], references: [id], onDelete: Cascade)\n  rating    Int\n  comment   String\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  @@map(\"reviews\")\n}\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nmodel User {\n  id           String   @id @default(uuid()) @db.Uuid\n  name         String\n  email        String   @unique\n  phone        String\n  passwordHash String   @map(\"password_hash\")\n  role         UserRole @default(TENANT)\n  isVerified   Boolean  @default(false) @map(\"is_verified\")\n  isBanned     Boolean  @default(false) @map(\"is_banned\")\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  listings            Listing[]            @relation(\"LandlordListings\")\n  refreshTokens       RefreshToken[]\n  favorites           Favorite[]\n  inquiries           Inquiry[]            @relation(\"TenantInquiries\")\n  reviews             Review[]             @relation(\"TenantReviews\")\n  aiSearchLogs        AiSearchLog[]\n  passwordResetTokens PasswordResetToken[]\n  verificationCodes   VerificationCode[]\n\n  @@map(\"users\")\n}\n\nmodel VerificationCode {\n  id        String    @id @default(uuid()) @db.Uuid\n  userId    String    @map(\"user_id\") @db.Uuid\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  codeHash  String    @map(\"code_hash\")\n  expiresAt DateTime  @map(\"expires_at\")\n  usedAt    DateTime? @map(\"used_at\")\n  attempts  Int       @default(0)\n  createdAt DateTime  @default(now()) @map(\"created_at\")\n\n  @@index([userId])\n  @@map(\"verification_codes\")\n}\n",
